B.U7=s([3080853389,4009807803,108490981,1755191456,1742743497,1819539462,3323374669,2058439996,1320762263,523703593,2774041647,3999235600,1020456567,5267269,484822773,2509904374,3829094717,3980703905,750411353,1233065467,3551421111,313897758,692821496,1923001374,2512953392,354935345,910306122,56837627,2754431625,1786485641,3381491646,2068922077,1206619809,2813966758,243800932,1538907915,3375067983,1699113700,1200893464,3036002376,3902826983,3021831498,2305905093,207648778,1267701193,1361970948,575674673,3065185436,1518521310,1802542930,3682747676],t.t)
